  "• 실시간 웹 푸시 알림 켜짐": "• အချိန်နှင့်တပြေးညီ ဝဘ်ပွတ်ရှ် သတိပေးချက် ဖွင့်ထားသည်",
  "• 직거래 후 시간 약속과 친절 칭찬 후기를 받으면 온도가 계속 상승합니다. (노쇼/사기 신고 시 하강)": "• လူကိုယ်တိုင် တွေ့ဆုံရောင်းချပြီးနောက် အချိန်တိကျမှုနှင့် ဖော်ရွေသည့် ချီးကျူးသုံးသပ်ချက်များကို လက်ခံရရှိပါက အပူချိန် ဆက်လက်တက်လာမည်ဖြစ်သည်။ (No-show/လိမ်လည်မှု တိုင်ကြားပါက ကျဆင်းမည်)",
