  "⏰ 직거래 약속 노쇼 (약속 장소에 안 나옴)": "⏰ လူချင်းတွေ့ဆုံ အရောင်းအဝယ် ချိန်းဆိုမှုပျက်ကွက်ခြင်း (ချိန်းဆိုထားသည့်နေရာသို့ မလာရောက်ခြင်း)",
  "⚠️ [Aligo SMS] API 키 또는 발신번호 미설정으로 시뮬레이션 모드로 동작합니다.": "⚠️ [Aligo SMS] API သော့ သို့မဟုတ် ပို့မည့်ဖုန်းနံပါတ် မသတ်မှတ်ထားသောကြောင့် သရုပ်ပြ (Simulation) စနစ်ဖြင့် လည်ပတ်နေပါသည်။",
