  "⚠️ 불법 취업 알선 / 브로커 / 사기 의심": "⚠️ တရားမဝင် အလုပ်အကိုင် ရှာဖွေပေးမှု / ပွဲစား / လိမ်လည်သည်ဟု သံသယရှိခြင်း",
  "⚠️ 알리고 실서버 응답 오류:": "⚠️ Aligo တိုက်ရိုက်ဆာဗာ တုံ့ပြန်မှု အမှားအယွင်း:",
  "⚡ D-14 묶음할인": "⚡ D-14 အုပ်စုလိုက် လျှော့ဈေး",
