  "✅ 신분증 자동 인식 완료!": "✅ ကိုယ်ရေးအမှတ်အသားကတ် (ID) အလိုအလျောက် မှတ်မိပြီးစီးပါပြီ!",
  "✅ 위치 설정이 완료되었습니다! 선택한 반경 내의 직거래 매물이 우선 표시됩니다.": "✅ တည်နေရာသတ်မှတ်မှု ပြီးစီးပါပြီ! ရွေးချယ်ထားသော အကွာအဝေးအတွင်းရှိ လူချင်းတွေ့ဆုံ အရောင်းအဝယ်ပစ္စည်းများကို ဦးစားပေးပြသမည်ဖြစ်ပါသည်။",
