  "구체적인 상황을 적어주시면 안전 운영팀이 신속히 조사 후 제재합니다.": "အသေးစိတ်အခြေအနေများကို ရေးသားပေးပို့ပါက လုံခြုံရေး စီမံခန့်ခွဲမှုအဖွဲ့မှ အမြန်ဆုံး စစ်ဆေးပြီး အရေးယူဆောင်ရွက်ပါမည်။",
