  "국세(소득세) 환급 예상분": "နိုင်ငံတော်အခွန် (ဝင်ငွေခွန်) ပြန်အမ်းငွေ ခန့်မှန်းချက်",
  "국세청 소득공제 영수증 연계": "ပြည်တွင်းအခွန်ဦးစီးဌာန ဝင်ငွေခွန်ကင်းလွတ်ခွင့် ပြေစာ ချိတ်ဆက်မှု",
