  "국적 선택 (모국어 상담 지원)": "နိုင်ငံအချင်းချင်း ရွေးချယ်ရန် (မိခင်ဘာသာစကားဖြင့် တိုင်ပင်ဆွေးနွေးမှု ပံ့ပိုးပေးသည်)",
  "국토부 실거래가 검증": "မြေယာနှင့် သယ်ယူပို့ဆောင်ရေး ဝန်ကြီးဌာန အမှန်တကယ် အရောင်းအဝယ်ဈေးနှုန်း စစ်ဆေးအတည်ပြုခြင်း",
  "궁금한 점, 따뜻한 이야기, 나눔/모임 등을 자유롭게 적어보세요. (17개국어로 자동 번역됩니다)": "သိလိုသည်များ၊ နွေးထွေးသော ဇာတ်လမ်းများ၊ မျှဝေခြင်း/စုဝေးခြင်းများကို လွတ်လပ်စွာ ရေးသားကြည့်ပါ။ (ဘာသာစကား ၁၇ မျိုးဖြင့် အလိုအလျောက် ဘာသာပြန်ပေးပါမည်)",
  "귀국": "နိုင်ငံပြန်မည်",
  "귀국 근로자 전용": "နိုင်ငံပြန်မည့် အလုပ်သမားများအတွက် သီးသန့်",
  "귀국 급처분이라 이미 많이 내린 가격이에요 ㅠㅠ 대신 오시면 주방용품이나 옷걸이 무료로 더 챙겨드릴게요!": "နိုင်ငံပြန်ရန် အမြန်ရှင်းထုတ်ရောင်းချခြင်းဖြစ်၍ ဈေးကို အများကြီး လျှော့ချပြီးသားဖြစ်ပါသည် ㅠㅠ တကယ်လို့ လာမယ်ဆိုရင် မီးဖচ့်သုံးပစ္စည်းများ သို့မဟုတ် အဝတ်ချိတ်များကို အလကား ထပ်ပေးပါမယ်!",
  "귀국 무빙 묶음": "နိုင်ငံပြန်ရန် ရွှေ့ပြောင်းပစ္စည်း အထုပ်လိုက်",
  "귀국 무빙세일": "နိုင်ငံပြန်ရန် ရွှေ့ပြောင်းပစ္စည်း အရောင်းဆိုင်",
