  "냉장고·세탁기·밥솥 가전 가구 풀세트 급처분 매물": "ရေခဲသေတ္တာ၊ အဝတ်လျှော်စက်၊ ထမင်းပေါင်းအိုး အိမ်သုံးလျှပ်စစ်ပစ္စည်းနှင့် ပရိဘောဂ အစုံလိုက် အမြန်ရှင်းလင်းရောင်းချမည့်ပစ္စည်း",
  "네! 가까운 편의점(CU, GS25, 세븐일레븐) 카운터에서 \"화성시 종량제 봉투 10리터나 20리터 주세요\" 하시면 현금이나 카드로 바로 살 수 있어요!": "ဟုတ်ကဲ့! အနီးနားရှိ 24နာရီ စတိုးဆိုင် (CU, GS25, Seven Eleven) ကောင်တာမှာ \"Hwaseong-si အမှိုက်အိတ် 10လီတာ ဒါမှမဟုတ် 20လီတာ ပေးပါ\" လို့ ပြောလိုက်ရင် ငွေသား (သို့) ကတ်နဲ့ ချက်ချင်း ဝယ်လို့ရပါတယ်!",
  "네, 안녕하세요! 물건 상태 아주 깨끗하고 바로 가져가실 수 있습니다. [${item.region}] 쪽으로 오실 수 있나요? 편하게 1:1 번역 채팅 주세요!": "ဟုတ်ကဲ့၊ မင်္ဂလာပါ! ပစ္စည်းအခြေအနေ အရမ်းသန့်ပြီး ချက်ချင်း ယူသွားနိုင်ပါတယ်။ [${item.region}] ဘက်ကို လာနိုင်ပါသလား? အဆင်ပြေရင် 1:1 ဘာသာပြန် ချတ် လှမ်းခဲ့ပေးပါ!",
  "네, 좋습니다! 그때 뵐게요.": "ဟုတ်ကဲ့၊ ကောင်းပါတယ်။ အဲဒီအချိန်ကျရင် တွေ့မယ်နော်။",
  "네고": "ဈေးဆစ်ခြင်း",
  "네이버 (블로그/카페)": "Naver (ဘလော့ဂ်/ကဖေး)",
