  "노출이 심한 사진, 성인용품, 음란성 이미지 또는 성희롱 사진 게시": "အလွန်အမင်း ကိုယ်အင်္ဂါပေါ်လွင်သော ဓာတ်ပုံများ၊ အရွယ်ရောက်ပြီးသူသုံး ပစ္စည်းများ၊ အပြာစာပေ ရုပ်ပုံများ သို့မဟုတ် လိင်ပိုင်းဆိုင်ရာ వేధిမှု ဓာတ်ပုံများ တင်ခြင်း",
  "는 사람의 따뜻한 체온처럼 가입 시 주어지는 기본 신뢰 점수입니다.": "သည် လူတစ်ဦး၏ နွေးထွေးသော ကိုယ်အပူချိန်ကဲ့သို့ပင် အသسင်းဝင်ချိန်တွင် ပေးအပ်သည့် အခြေခံယုံကြည်မှုရမှတ် ဖြစ်ပါသည်။",
