  "님과 거래 예약중": "နှင့် အရောင်းအဝယ် ကြိုတင်予約 (ချိတ်ဆက်) ပြုလုပ်နေသည်",
  "님과 거래 완료됨": "နှင့် အရောင်းအဝယ် ပြီးဆုံးပါပြီ",
  "님과의 거래는 어떠셨나요?": "နှင့် ပြုလုပ်ခဲ့သော အရောင်းအဝယ်သည် ဘယ်လိုရှိပါသလဲ?",
