  "대표사진": "ပင်မပုံ",
  "대표자:": "ဥက္ကဋ္ဌ / တာဝန်ခံ -",
  "대한민국 1등 외국인 근로자 안심 직거래 마켓": "တောင်ကိုရီးယားနိုင်ငံ၏ နံပါတ် (၁) နိုင်ငံခြားသား အလုပ်သမားများအတွက် စိတ်ချယုံကြည်ရသော တိုက်ရိုက်အရောင်းအဝယ်ဈေးကွက်",
  "대한민국 1등 외국인 근로자 종합 플랫폼": "တောင်ကိုရီးယားနိုင်ငံ၏ နံပါတ် (၁) နိုင်ငံခြားသား အလုပ်သမားများဆိုင်ရာ ဘက်စုံပလက်ဖောင်း",
  "대한민국 1등 외국인 종합 슈퍼앱 케이티알에스 연계 외국인 전용 0원 안심 중고거래 & 귀국 무빙세일 & 동네생활 커뮤니티": "ကိုရီးယားနိုင်ငံ၏ နံပါတ် (၁) နိုင်ငံခြားသားများဆိုင်ရာ စူပါအက်ပ် KTRS ချိတ်ဆက်ထားသော နိုင်ငံခြားသားများအတွက်သာ 0 ဝမ် စိတ်ချရသော အသုံးအဆောင်ပစ္စည်းအရောင်းအဝယ် & နိုင်ငံပြန်ရန် ရွှေ့ပြောင်းပစ္စည်းအရောင်းဆိုင် & ရပ်ကွက်နေထိုင်မှုအသိုင်းအဝိုင်း",
  "대한민국 1등 외국인 종합 슈퍼앱 케이티알에스 연계 외국인 전용 0원 안심 중고거래 &amp; 귀국 무빙세일 &amp; 동네생활 커뮤니티": "ကိုရီးယားနိုင်ငံ၏ နံပါတ် (၁) နိုင်ငံခြားသားများဆိုင်ရာ စူပါအက်ပ် KTRS ချိတ်ဆက်ထားသော နိုင်ငံခြားသားများအတွက်သာ 0 ဝမ် စိတ်ချရသော အသုံးအဆောင်ပစ္စည်းအရောင်းအဝယ် &amp; နိုင်ငံပြန်ရန် ရွှေ့ပြောင်းပစ္စည်းအရောင်းဆိုင် &amp; ရပ်ကွက်နေထိုင်မှုအသိုင်းအဝိုင်း",
  "대한민국 No.1 외국인 근로자 전용 0원 수수료 중고거래 & 귀국 무빙세일 플랫폼! 17개국어 실시간 자동 번역 채팅, 평택·안산·화성 전국 공단 도보 5분 안심 직거래, 최대 1000만원 세금 환급 원스톱 연계": "တောင်ကိုရီးယားနိုင်ငံ၏ နံပါတ် (၁) နိုင်ငံခြားသား အလုပ်သမားများအတွက်သာ သီးသန့် ဝန်ဆောင်ခ 0 ကျပ်ဖြင့် အသုံးအဆောင်ဟောင်း ရောင်းဝယ်ရေးနှင့် ပြည်တော်ပြန်ပစ္စည်းရှင်းလင်းရေး ပလပ်ဖောင်း! ဘာသာစကား ၁၇ မျိုး တိုက်ရိုက် အလိုအလျောက် ဘာသာပြန်ချက်တင်၊ ပျော့တက်၊ အန်ဆန်၊ ဟွာဆောင် စက်မှုဇုန်များတွင် လမ်းလျှောက် 5 မိနစ်အကွာအဝေး စိတ်ချရသော တိုက်ရိုက်အရောင်းအဝယ်၊ အများဆုံး ဝမ် ၁,၀၀၀ အထိ အခွန်ပြန်အမ်းငွေ One-stop ချိတ်ဆက်မှု",
  "대한민국 국세청 조세특례제한법 제30조에 따른 외국인 법적 권리": "တောင်ကိုရီးယားနိုင်ငံ ပြည်တွင်းအခွန်ဦးစီးဌာန အခွန်ဆိုင်ရာ အထူးဥပဒေ ပုဒ်မ 30 အရ နိုင်ငံခြားသားများ၏ တရားဝင် အခွင့်အရေး",
  "대한민국 원화 단위": "တောင်ကိုရီးယား ဝွန်ငွေကြေး ယူနစ်",
