  "물건 상태가 설명과 똑같아요": "ပစ္စည်းအခြေအနေက ဖော်ပြချက်အတိုင်း အတိအကျဖြစ်ပါသည်",
  "물건을 직접 만나 확인하기 전에 계좌이체나 계약금을 요구하는 것은 100% 사기 수법입니다. 반드시 직거래 현장에서 확인 후 대금을 지급하세요.": "ပစ္စည်းကို ကိုယ်တိုင်တွေ့ဆုံစစ်ဆေးခြင်းမပြုမီ ငွေလွှဲခိုင်းခြင်း သို့မဟုတ် စရန်ငွေတောင်းခံခြင်းသည် 100% လိမ်လည်သည့်နည်းလမ်း ဖြစ်ပါသည်။ တိုက်ရိုက်တွေ့ဆုံရာနေရာတွင် သေချာစစ်ဆေးပြီးမှသာ ငွေပေးချေပါ။",
  "물건을 직접 만나서 확인하기 전에 계좌이체/선입금을 요구하는 것은 100% 사기 수법입니다. 반드시 직거래 현장에서 확인 후 대금을 전달하세요.": "ပစ္စည်းကို ကိုယ်တိုင်တွေ့ဆုံစစ်ဆေးခြင်းမပြုမီ ငွေလွှဲခိုင်းခြင်း/ငွေကြိုတင်တောင်းခံခြင်းသည် 100% လိမ်လည်သည့်နည်းလမ်း ဖြစ်ပါသည်။ တိုက်ရိုက်တွေ့ဆုံရာနေရာတွင် သေချာစစ်ဆေးပြီးမှသာ ငွေပေးအပ်ပါ။",
  "물건의 상태, 사용 기간, 직거래 가능한 시간대를 적어주세요. 모국어로 작성하셔도 구매자에게 자동 번역됩니다.": "ပစ္စည်းအခြေအနေ၊ အသုံးပြုသည့်ကာလနှင့် လူကိုယ်တိုင် လဲလှယ်ဝယ်ယူနိုင်သည့် အချိန်များကို ရေးသားပေးပါ။ သင့်မိခင်ဘာသာစကားဖြင့် ရေးသားသော်လည်း ဝယ်ယူသူထံသို့ အလိုအလျောက် ဘာသာပြန်ပေးပါမည်။",
