  "박철수 (반장님)": "ပါ့ချောဆူ (ခေါင်းဆောင်)",
  "반가워요! 저 평택역 근처 사는데 일요일에 시간 괜찮으시면 커피 한잔하면서 한국어 알려드릴게요! 환영합니다 :)": "တွေ့ရတာ ဝမ်းသာပါတယ်! ကျွန်တော်က Pyeongtaek ဘူတာရုံနားမှာ နေတာပါ။ တနင်္ဂနွနေ့ အချိန်ရရင် ကော်ဖီသောက်ရင်း ကိုရီးယားစာ သင်ပေးမယ်နော်! ကြိုဆိုပါတယ် :)",
