  "반드시 만나서 물건을 본 뒤 현금/이체하기": "လူကိုယ်တိုင်တွေ့ဆုံ၍ ပစ္စည်းကို သေချာစစ်ဆေးပြီးမှ ငွေသား/လွှဲပြောင်းပေးချေပါ",
  "반드시 직접 만나 물건을 꼼꼼히 확인한 후 대금을 지급하세요.": "ပစ္စည်းကို လူကိုယ်တိုင်တွေ့ဆုံ၍ သေချာစွာ စစ်ဆေးပြီးမှသာ ငွေပေးချေပါ။",
  "반드시 케이마켓의 안심 자동 번역 채팅방 안에서만 안전하게 거래를 진행하세요.": "ကေမားကတ်၏ စိတ်ချရသော အလိုအလျောက် ဘာသာပြန် ချတ်ခန်းအတွင်း၌သာ လုံခြုံစွာ အရောင်းအဝယ်ပြုလုပ်ပါ။",
