  "비매너 및 사기 의심 회원 신고 / 차단하기": "ယဉ်ကျေးမှုမရှိခြင်းနှင့် လိမ်လည်သည်ဟု သံသယရှိသော အဖွဲ့ဝင်ကို တိုင်ကြားခြင်း / ပိတ်ဆို့ခြင်း",
