  "빛반사 없이 0.5초 빠르고 안전하게 자동 인식": "အလင်းပြန်ခြင်းမရှိဘဲ ၀.၅ စက္ကန့်အတွင်း မြန်ဆန်လုံခြုံစွာ အလိုအလျောက် မှတ်မိစေသည်",
