  "상세 사유 (선택)": "အသေးစိတ် အကြောင်းရင်း (ရွေးချယ်ရန်)",
  "상세 설명": "상세 설명",
  "상태변경 / 끌올": "အခြေအနေပြောင်းလဲရန် / ထိပ်ဆုံးသို့တင်ရန်",
  "상품 사진": "ပစ္စည်း ဓာတ်ပုံ",
  "상품 카테고리를 선택해 주세요": "ကုန်ပစ္စည်း အမျိုးအစားကို ရွေးချယ်ပေးပါ",
  "상품권": "လက်ဆောင်လက်မှတ်",
  "상품권 요구 및 가짜 결제 링크 유도는 전형적인 사기 범죄입니다. K-Market 공식 채팅 외의 외부 링크는 절대 클릭하거나 로그인하지 마세요.": "လက်ဆောင်कु폰 (Gift Card) တောင်းဆိုခြင်းနှင့် အတုအယောင် ငွေပေးချေမှုလင့်ခ်များသို့ လမ်းညွှန်ခြင်းသည် ပုံစံတကျ လိမ်လည်မှုတစ်ခု ဖြစ်ပါသည်။ K-Market ၏ တရားဝင်ချတ်ပြင်ပရှိ ပြင်ပလင့်ခ်များကို လုံးဝ (လုံးဝ) နှိပ်ခြင်း သို့မဟုတ် အကောင့်ဝင်ခြင်း မပြုလုပ်ပါနှင့်။",
  "상품권을 요구하거나 외부 안전결제 링크로 로그인을 유도하는 것은 피싱 사기입니다. K-Market 공식 채팅 외의 링크는 클릭 금지입니다.": "လက်ဆောင်ကတ်တောင်းဆိုခြင်း သို့မဟုတ် ပြင်ပလုံခြုံသော ငွေပေးချေမှုလင့်ခ်များမှတစ်ဆင့် အကောင့်ဝင်ရန် လမ်းညွှန်ခြင်းသည် ဖစ်ရှင်းင်း (Phishing) လိမ်လည်မှု ဖြစ်ပါသည်။ K-Market တရားဝင်ချတ်ပြင်ပရှိ လင့်ခ်များကို လုံးဝမနှိပ်ရပါ။",
