  "서해선 원시역 1번 출구 엘리베이터 앞": "ဆောဟယ်လိုင်း ဝန်ရှီဘူတာ အမှတ် (၁) ထွက်ပေါက် စက္ကူလှေကား/ဓာတ်လှေကား ရှေ့",
