  "신고 및 차단 대상 회원:": "တိုင်ကြားခြင်းနှင့် ပိတ်ဆို့ခံရမည့် အဖွဲ့ဝင် -",
  "신고 사유 선택": "တိုင်ကြားရသည့် အကြောင်းရင်းကို ရွေးချယ်ပါ",
