  "신고된 내용은 24시간 관리자 관제 센터로 즉시 전송되며, 검토 후 해당 사용자는 영구 퇴출 처리됩니다.": "တိုင်ကြားထားသော အချက်အလက်များကို ၂၄ နာရီ စီမံခန့်ခွဲရေး ထိန်းချုပ်ရေးစင်တာသို့ ချက်ချင်း ပို့ဆောင်မည်ဖြစ်ပြီး စစ်ဆေးပြီးနောက် သက်ဆိုင်ရာ အသုံးပြုသူကို အပြီးအပိုင် ထုတ်ပယ်မည်ဖြစ်သည်။",
