  "아직 찜한 물건이 없습니다.": "စိတ်ကြိုက် မှတ်သားထားသော ပစ္စည်း မရှိသေးပါ။",
  "안내 내용을 모두 확인했습니다": "လမ်းညွှန်ချက် အချက်အလက်များကို အားလုံး ဖတ်ရှုစစ်ဆေးပြီးပါပြီ",
  "안내 내용을 확인해 주세요": "လမ်းညွှန်ချက် အချက်အလက်များကို စစ်ဆေးပေးပါ",
  "안내창 닫기": "လမ်းညွှန် ဝင်းဒိုးကို ပိတ်ရန်",
  "안녕하세요": "မင်္ဂလာပါ",
  "안녕하세요 친구! 저도 평택 시장 근처에 사는데 이번 주말에 저도 같이 껴도 될까요?!": "မင်္ဂလာပါ သူငယ်ချင်း! ကျွန်တော်လည်း ပျောတက် (Pyeongtaek) ဈေးနားမှာ နေတာဆိုတော့ ဒီသီတင်းပတ်အဆုံးမှာ ကျွန်တော်ပါ လိုက်လို့ရမလားဟင်?!",
  "안녕하세요! 무빙세일 세탁기+밥솥 세트 아직 있나요? 오늘 저녁 7시에 포승공단 기숙사 앞에서 직거래 가능할까요?": "မင်္ဂလာပါရှင်! ရွှေ့ပြောင်းပစ္စည်း အရောင်းဆိုင်က အဝတ်လျှော်စက် + ထမင်းပေါင်းအိုး စုံတွဲက သုံးနိုင်သေးလားရှင်? ဒီနေ့ ညနေ ၇ နာရီမှာ ဖိုဆောင်းစက်မှုဇုန် ကျောင်းသားအဆောင်ရှေ့မှာ လူချင်းတွေ့ပြီး တိုက်ရိုက်ဝယ်ယူလို့ ရနိုင်မလားရှင်?",
  "안녕하세요! 아직 판매 중인가요?": "မင်္ဂလာပါခင်ဗျာ! ပစ္စည်း ရောင်းချဆဲ ရှိပါသေးသလား?",
  "안녕하세요! 한국에 온 지 8개월 된 호랑이라고 합니다. 주말마다 혼자 방에만 있으니까 너무 외로워서 글 올려요. 이번 주 일요일 오후에 같이 맛있는 거 먹고 서로 언어 교환(베트남어 ↔ 한국어) 하실 동네 친구분 계신가요? 국적 상관없이 편하게 댓글 남겨주세요!": "မင်္ဂလာပါ! ကိုရီးယားကိုရောက်တာ ၈ လရှိပြီဖြစ်တဲ့ Horang လို့ခေါ်ပါတယ်။ စနေ၊ တနင်္ဂနွေတိုင်း အခန်းထဲမှာပဲ တစ်ယောက်တည်း ရှိနေတော့ အရမ်းဘဝတစ်ယောက်တည်းဆန်လို့ ပို့စ်တင်လိုက်ပါတယ်။ ဒီတစ်ပတ် တနင်္ဂနွေနေ့ နေ့လယ်မှာ အတူတူ အရသာရှိတာတွေစားပြီး ဘာသာစကား အပြန်အလှန်ဖလှယ် (ဗီယက်နမ် ↔ ကိုရီးယား) လုပ်မယ့် ရပ်ကွက်ထဲက သူငယ်ချင်းတွေ ရှိပါသလား? နိုင်ငံူမရွေး စိတ်အေးလက်အေး မှတ်ချက်ရေးခဲ့ပေးကြပါ!",
  "안녕하세요, 네 물건 그대로 다 있습니다! 오늘 저녁 7시 기숙사 정문에서 봬요, 직접 테스트해보실 수 있게 가지고 나갈게요.": "မင်္ဂလာပါ၊ ဟုတ်ကဲ့ ပစ္စည်းတွေ အကုန်အတိုင်းရှိပါတယ်! ဒီနေ့ ညနေ ၇ နာရီ အဆောင်ရှေ့တံခါးဝမှာ တွေ့ကြမယ်နော်၊ ကိုယ်တိုင် စမ်းသပ်ကြည့်လို့ရအောင် သယ်လာခဲ့ပေးပါမယ်။",
