  "예: 통돌이 세탁기 및 쿠쿠 밥솥 묶음 귀국 세일합니다": "ဥပမာ - အဝတ်လျှော်စက်နှင့် Cuckoo ထမင်းပေါင်းအိုး အထုပ်လိုက် နိုင်ငံပြန်ရောင်းချခြင်း ဖြစ်သည်",
