  "지정 직거래 만남 장소": "သတ်မှတ်ထားသော လူផ្ទាល់တွေ့ဆုံငွေချေမည့် နေရာ",
  "지정된 직거래 만남 장소 핀": "သတ်မှတ်ထားသော ကိုယ်တိုင်တွေ့ဆုံရာ နေရာပင်နံပါတ်",
  "직거래 만남 장소": "ကိုယ်တိုင်တွေ့ဆုံမည့်နေရာ",
  "직거래 약속 1시간 전 리마인더": "ကိုယ်တိုင်တွေ့ဆုံရန် ၁ နာရီအလို သတိပေးချက်",
  "직거래 약속 1시간 전 자동 리마인더 알림": "ကိုယ်တိုင်တွေ့ဆုံရန် ၁ နာရီအလို အလိုအလျောက် သတိပေးချက်",
  "직거래 약속 핀을 저장하고 상대방에게 전송하기": "တွေ့ဆုံမည့်နေရာ ပင်ကိုသိမ်းဆည်းပြီး အခြားသူထံ ပို့ရန်",
  "직거래 완료 및 상대방 매너온도 평가하기": "လက်ချင်းဆက် အရောင်းအဝယ် ပြီးဆုံးပြီး တစ်ဖက်လူ၏ ကျင့်ဝတ်အပူချိန်ကို အကဲဖြတ်ရန်",
  "직거래 완료 🛍️": "လက်ချင်းဆက် အရောင်းအဝယ် ပြီးဆုံးပါပြီ 🛍️",
  "직거래 장소 지도": "ကိုယ်တိုင်တွေ့ဆုံမည့်နေရာ မြေပုံ",
  "직거래 주소 & 만남 장소 (지도 핀 이동 가능)": "တွေ့ဆုံမည့်လိပ်စာနှင့်နေရာ (မြေပုံပင်ကို ရွှေ့နိုင်သည်)",
  "직거래 후기 작성하기": "လက်ချင်းဆက် အရောင်းအဝယ် သုံးသပ်ချက် ရေးသားရန်",
  "직접 만나서 물건 상태를 확인한 후": "ကိုယ်တိုင်ကိုယ်ကျ တွေ့ဆုံ၍ ပစ္စည်းအခြေအနေကို စစ်ဆေးပြီးနောက်",
  "직접 방문 (Direct / 북마크)": "ကိုယ်တိုင် လာရောက်လည်ပတ်ခြင်း (Direct / Bookmark)",
  "진접읍 부평로뒷들1길": "ဂျින්ဂျော့အွပ်၊ ပူဖ្យောင်းရိုးဒွတ်ဒึល ၁ လမ်း",
  "질문: 노란색 종량제 쓰레기봉투는 어디서 사나요? 편의점에서도 파나요?": "မေးခွန်း - အဝါရောင် အမှိုက်အိတ်တွေကို ဘယ်မှာ ဝယ်လို့ရပါလဲ။ စတိုးဆိုင်တွေမှာလည်း ရောင်းပါသလား။",
  "찜 목록에서 삭제": "စိတ်ကြိုက်စာရင်းမှ ဖျက်မည်",
  "찜 취소": "စိတ်ကြိုက် မှတ်သားမှုကို ပယ်ဖျက်မည်",
  "찜한 매물 & 마이페이지": "စိတ်ကြိုက် မှတ်သားထားသော ပစ္စည်းများနှင့် ကိုယ်ပိုင် စာမျက်နှာ",
  "찜한 매물 ()": "စိတ်ကြိုက် မှတ်သားထားသော ပစ္စည်းများ ()",
  "차단 시 이 회원의 매물과 메시지가 나에게 더 이상 보이지 않습니다.": "ပိတ်ဆို့လိုက်ပါက ဤအဖွဲ့ဝင်၏ ပစ္စည်းများနှင့် မက်ဆေ့ချ်များကို ကျွန်ုပ်ထံတွင် ထပ်မံမြင်တွေ့ရတော့မည် မဟုတ်ပါ။",
  "채팅 도착 및 관심 매물 등록 시 즉시 알려드려요!": "ချတ်ရောက်ရှိလာသောအခါနှင့် စိတ်ဝင်စားသော ပစ္စည်းများကို မှတ်ပုံတင်သည့်အခါ ချက်ချင်း အသိပေးပါမည်။",
  "채팅 응답이 매우 빨라요": "ချတ်ပြန်ကြားမှု အလွန်မြန်ဆန်သည်",
  "채팅 중 모욕적이거나 불쾌한 언행을 함": "ချတ်လုပ်နေစဉ်အတွင်း စော်ကားသော သို့မဟုတ် မနှစ်မြို့ဖွယ်ရာ စကားပြောဆိုမှုများ ပြုလုပ်ခြင်း",
  "채팅방이 시작되었습니다.": "ချတ်ခန်း စတင်နေပြီဖြစ်ပါသည်။",
  "첫 번째 거래 후기를 남겨보세요!": "ပထမဆုံး ငွေပေးငွေယူ သုံးသပ်ချက်ကို ချန်ထားခဲ့ပါ!",
  "첫 번째 따뜻한 댓글을 남겨보세요!": "ပထမဆုံး နွေးထွေးသော မှတ်ချက်ကို ရေးသားကြည့်ပါ!",
  "첫 번째로 동네 친구를 사귀거나 따뜻한 이야기를 올려보세요!": "ပထမဆုံးအနေဖြင့် ရပ်ကွက်ထဲက သူငယ်ချင်းဖွဲ့ပါ သို့မဟုတ် နွေးထွေးသော ဇာတ်လမ်းများကို တင်ကြည့်ပါ!",
  "첫 이야기 작성하기": "ပထမဆုံး ဇာတ်လမ်းကို ရေးသားရန်",
  "청소기": "လေဟာစုပ်စက် (ဗဟိုစုပ်စက် / ဖုန်စုပ်စက်)",
  "체류 기간 만료일": "နေထိုင်ခွင့် ကုန်ဆုံးရက်",
  "체류 비자 인증 완료": "နေထိုင်ခွင့် ဗီဇာ အတည်ပြုပြီး",
  "체류 연장 서류 팁, 외국인등록증 재발급 후기": "နေထိုင်ခွင့် သက်တမ်းတိုး စာရွက်စာတမ်း အကြံပြုချက်များ၊ နိုင်ငံခြားသား မှတ်ပုံတင်ကတ် အသစ်ပြန်ထုတ်ခြင်း အတွေ့အကြုံ",
  "체류비자 신분 확인됨": "နေထိုင်ခွင့် ဗီဇာ အဆင့်အတန်း အတည်ပြုပြီး",
