  "최고의 매너 이웃": "အကောင်းဆုံး စိတ်နေသဘောထားရှိသော အိမ်နီးနားချင်း",
  "최근": "မကြာသေးမီက",
  "최근 5년간 지나친 세금": "လွန်ခဲ့သော 5 နှစ်အတွင်း ပေးဆောင်ခဲ့ရသော အခွန်များ",
  "최근 5년간 한국에서 납부한 종합소득세 및 근로소득세": "လွန်ခဲ့သော 5 နှစ်အတွင်း ကိုရီးယားနိုင်ငံတွင် ပေးဆောင်ခဲ့သော အထွေထွေဝင်ငွေခွန်နှင့် လုပ်သားဝင်ငွေခွန်",
  "최근 거래 후기 ()": "לט်ဆုံး ငွေပေးငွေယူ သုံးသပ်ချက်များ ()",
  "최근 채팅 상대": "လတ်တလော ချတ်လုပ်ဖော်ရည်",
