  "최대 5,000만원": "အများဆုံး ဝန် ၅၀ သန်း",
  "최대 5,000만원 생활자금": "အများဆုံး ဝန် ၅၀ သန်း လူနေမှုဘဝ ရန်ပုံငွေ",
  "최대 85% 묶음 할인": "အများဆုံး ၈၅% အစုလိုက် အထူးလျှော့စျေး",
  "최대 대출 가능 한도": "အများဆုံး ချေးငွေရယူနိုင်သည့် ပမာဏကန့်သတ်ချက်",
  "추가하고 싶은 지역이나 안심 직거래 추천 장소를 적어주세요. (예: 안심존 편의점 앞, 지하철역 출구)": "ထည့်သွင်းလိုသော ဒေသ သို့မဟုတ် စိတ်ချရသော တိုက်ရိုက်အရောင်းအဝယ် အကြံပြုသည့်နေရာကို ရေးသားပေးပါ။ (ဥပမာ- စိတ်ချရသောဇုန် စတိုးဆိုင်ရှေ့၊ υπόγεια ရထားဘူထွက်ပေါက်)",
  "출퇴근용 자전거": "အလုပ်သွားအလုပ်ပြန် စက်ဘီး",
  "친구": "သူငယ်ချင်း",
  "친구님 힘내세요! 딸아이가 아빠를 정말 자랑스러워할 겁니다. 환절기 감기 조심하시고 따뜻한 밥 챙겨드세요!": "မိတ်ဆွေ ရဲတင်းပါ! သမီးငယ်လေးက ဖေဖေအတွက် တကယ်ကို ဂုဏ်ယူနေမှာပါ။ ရာသီဥတုအကူးအပြောင်းမှာ အအေးမိခြင်းမှ သတိထားပြီး ထမင်းနွေးနွေးလေးတွေ စားပါ!",
  "친구에게 매물 공유하기": "သူငယ်ချင်းထံ အိမ်ခြံမြေ/အခန်း ကြော်ငြာကို မျှဝေရန်",
  "친절하고 매너가 최고예요": "ယဉ်ကျေးပြီး စိတ်နေသဘောထား အကောင်းဆုံးပါပဲ",
  "친절한": "ယဉ်ကျေးပျူငှာသော",
  "침구 매트커버 아망떼 퀸Q사이즈 매...": "အိပ်ယာခင်း မက်တတ်ကာဗာ Amantee Queen Q Size မက်...",
  "카메라 열기 / 신분증 촬영하고 43.5℃ 받기 ➔": "ကင်မရာဖွင့်ရန် / မှတ်ပုံတင်ဓာတ်ပုံရိုက်ပြီး 43.5℃ ရယူရန် ➔",
  "카자흐어": "ကဇာတ်စတန်ဘာသာ",
  "카카오 지도 길찾기 연동": "Kakao မြေပုံ လမ်းညွှန်ချိတ်ဆက်မှု",
  "카카오톡": "ကာကာအိုတော့ခ် (KakaoTalk)",
  "카카오톡 (오픈채팅/알림톡)": "KakaoTalk (အဖွင့်ချတ်/အသိပေးချက်)",
  "카카오톡, 라인, 텔레그램 등 외부 메신저로 유도하여 사기 피해를 입히는 사례가 발생하고 있습니다. 안전을 위해 K-Market 안심 번역 채팅 내에서만 대화하세요.": "KakaoTalk, Line, Telegram စသည့် ပြင်ပ မက်ဆေ့ချ်အက်ပ်များဆီသို့ လမ်းကြောင်းပေးကာ လိမ်လည်ခံရသည့် ဖြစ်စဉ်များ ရှိနေပါသည်။ လုံခြုံရေးအတွက် K-Market ၏ စိတ်ချရသော ဘာသာပြန် ချတ်အတွင်း၌သာ စကားပြောဆိုပါ။",
  "카카오톡, 라인, 텔레그램 등으로 유도하여 사기 피해를 입히는 사례가 많습니다. 안전을 위해 실시간 번역 채팅 내에서만 대화하세요.": "KakaoTalk, Line, Telegram စသည်တို့ဆီသို့ လမ်းကြောင်းပေး၍ လိမ်လည်ခံရသည့် ဖြစ်စဉ်များစွာ ရှိပါသည်။ လုံခြုံရေးအတွက် အချိန်နှင့်တပြေးညီ ဘာသာပြန် ချတ်အတွင်း၌သာ စကားပြောဆိုပါ။",
  "카카오톡/라인 등 외부 메신저 유도를 거절하세요": "KakaoTalk/Line စသည့် ပြင်ပမက်ဆေ့ချ်အက်ပ်များသို့ ခေါ်ဆောင်ခြင်းကို ငြင်းပယ်ပါ",
  "카테고리 선택": "အမျိုးအစား ရွေးချယ်ရန်",
  "카테고리별 매물 찾기": "အမျိုးအစားအလိုက် ပစ္စည်းများ ရှာဖွေရန်",
